ALTER TABLE public.salons ADD COLUMN access_enabled boolean NOT NULL DEFAULT true, ADD COLUMN block_reason text NOT NULL DEFAULT '', ADD COLUMN blocked_at timestamptz, ADD COLUMN blocked_by uuid, ADD COLUMN released_at timestamptz, ADD COLUMN suspended_until timestamptz, ADD COLUMN archived_at timestamptz, ADD COLUMN subscription_due_date date;
CREATE TABLE public.log_acoes_master(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),salon_id uuid NOT NULL REFERENCES public.salons(id),action text NOT NULL,reason text NOT NULL DEFAULT '',performed_by uuid NOT NULL,performed_at timestamptz NOT NULL DEFAULT now(),previous_data jsonb NOT NULL);
GRANT SELECT ON public.log_acoes_master TO authenticated; GRANT ALL ON public.log_acoes_master TO service_role;
ALTER TABLE public.log_acoes_master ENABLE ROW LEVEL SECURITY;
CREATE POLICY master_log_read ON public.log_acoes_master FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'super_admin'));
CREATE FUNCTION public.salon_access_allowed(_salon uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'super_admin') OR EXISTS(SELECT 1 FROM public.salons WHERE id=_salon AND archived_at IS NULL AND status='ativo' AND (access_enabled OR (suspended_until IS NOT NULL AND suspended_until<=now()))) $$;
REVOKE ALL ON FUNCTION public.salon_access_allowed(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.salon_access_allowed(uuid) TO authenticated,anon;
CREATE FUNCTION public.master_set_salon_access(_salon uuid,_action text,_reason text,_days integer DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE old_row public.salons; BEGIN
IF NOT public.has_role(auth.uid(),'super_admin') THEN RAISE EXCEPTION 'Acesso exclusivo da desenvolvedora master'; END IF;
IF _action NOT IN ('bloquear','liberar','suspender','arquivar') THEN RAISE EXCEPTION 'Ação inválida'; END IF;
IF _action<>'liberar' AND length(trim(_reason))<3 THEN RAISE EXCEPTION 'Informe o motivo'; END IF;
IF _action='suspender' AND (_days IS NULL OR _days<1 OR _days>365) THEN RAISE EXCEPTION 'Prazo inválido'; END IF;
SELECT * INTO old_row FROM public.salons WHERE id=_salon FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Salão não encontrado'; END IF;
UPDATE public.salons SET access_enabled=(_action='liberar'),block_reason=CASE WHEN _action='liberar' THEN '' ELSE trim(_reason) END,blocked_at=CASE WHEN _action='liberar' THEN blocked_at ELSE now() END,blocked_by=CASE WHEN _action='liberar' THEN blocked_by ELSE auth.uid() END,released_at=CASE WHEN _action='liberar' THEN now() ELSE released_at END,suspended_until=CASE WHEN _action='suspender' THEN now()+make_interval(days=>_days) ELSE NULL END,archived_at=CASE WHEN _action='arquivar' THEN now() WHEN _action='liberar' THEN NULL ELSE archived_at END WHERE id=_salon;
INSERT INTO public.log_acoes_master(salon_id,action,reason,performed_by,previous_data)VALUES(_salon,_action,trim(_reason),auth.uid(),to_jsonb(old_row)); END $$;
REVOKE ALL ON FUNCTION public.master_set_salon_access(uuid,text,text,integer) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.master_set_salon_access(uuid,text,text,integer) TO authenticated;
CREATE FUNCTION public.protect_salon_access_fields() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NOT public.has_role(auth.uid(),'super_admin') AND (to_jsonb(new)-ARRAY['name','logo_url','brand_color','name_article','plan_id','status','reseller_id','city','slug','timezone']) IS DISTINCT FROM (to_jsonb(old)-ARRAY['name','logo_url','brand_color','name_article','plan_id','status','reseller_id','city','slug','timezone']) THEN RAISE EXCEPTION 'Apenas master altera controle de acesso'; END IF; RETURN new; END $$;
CREATE TRIGGER protect_salon_access BEFORE UPDATE ON public.salons FOR EACH ROW EXECUTE FUNCTION public.protect_salon_access_fields();
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['appointments','professionals','professions','services','config_agente_secretario','salon_connections','salon_clients','team_messages','supplier_brands','supplier_products','supplier_orders','month_closings','memoria_ia','fila_mensagens_ia','lead_conversations','whatsapp_outbound'] LOOP EXECUTE format('CREATE POLICY salon_access_restriction ON public.%I AS RESTRICTIVE FOR ALL TO authenticated USING (public.salon_access_allowed(salon_id)) WITH CHECK (public.salon_access_allowed(salon_id))',t); END LOOP; END $$;